import collections
from collections import defaultdict
def build():
    adj=defaultdict(set)
    def link(a,b): adj[a].add(b); adj[b].add(a)
    for s in ['s2','s3','s4']: link('s1',s)
    hosts=[]; hi=1
    for s in ['s2','s3','s4']:
        for _ in range(3):
            h='h%d'%hi; hi+=1; link(h,s); hosts.append(h)
    return adj,hosts,{'s1','s2','s3','s4'}
def sp(src,dst,adj):
    prev={src:None}; q=collections.deque([src])
    while q:
        u=q.popleft()
        if u==dst: break
        for v in sorted(adj[u]):
            if v not in prev: prev[v]=u; q.append(v)
    if dst not in prev: return None
    p=[];c=dst
    while c is not None: p.append(c); c=prev[c]
    return p[::-1]
def tot(adj,hosts,sw):
    t=0;pairs=0
    for a in hosts:
        for b in hosts:
            if a==b: continue
            p=sp(a,b,adj)
            if not p: continue
            pairs+=1; t+=sum(1 for n in p if n in sw)
    return t,pairs
def uses(p,u,v):
    return any((p[i]==u and p[i+1]==v) or (p[i]==v and p[i+1]==u) for i in range(len(p)-1))

# baseline
adj,hosts,sw=build(); base,bp=tot(adj,hosts,sw); print('baseline',base,bp)

for fail in [('s1','s2'),('h1','s2')]:
    adj,hosts,sw=build()
    # affected-only accounting: pairs whose old path used the failed link
    old={}
    for a in hosts:
        for b in hosts:
            if a!=b: old[(a,b)]=sp(a,b,adj)
    affected=[k for k,p in old.items() if uses(p,*fail)]
    adj[fail[0]].discard(fail[1]); adj[fail[1]].discard(fail[0])
    reinst=0; feas=0
    for (a,b) in affected:
        p=sp(a,b,adj)
        if p: feas+=1; reinst+=sum(1 for n in p if n in sw)
    after,ap=tot(adj,hosts,sw)
    print('fail',fail,'affected pairs',len(affected),'affected-only reinstalled',reinst,'| full reinstall all-pairs',after,'(pairs',ap,')')

# with redundant leaf-leaf link s2-s3 then fail s1-s2
adj,hosts,sw=build(); adj['s2'].add('s3'); adj['s3'].add('s2')
old={(a,b):sp(a,b,adj) for a in hosts for b in hosts if a!=b}
aff=[k for k,p in old.items() if uses(p,'s1','s2')]
adj['s1'].discard('s2'); adj['s2'].discard('s1')
r=sum(sum(1 for n in sp(a,b,adj) if n in sw) for (a,b) in aff if sp(a,b,adj))
print('redundant variant: affected',len(aff),'reinstalled',r)
